INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24016, 2, "", "", 0, 10, 0, 1, 20001, 0, 319);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (23001, 2, "", "", 0, 10, 0, 20, 20001, 0, 320);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "リリ", "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 1, 0, 1, 40011, 125801, 321);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "クリア", "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 1, 2, 0, 1, 40011, 126001, 322);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "プレシア", "んーと。\nこれ、あげる。\nはい", 1, 3, 0, 1, 40011, 126101, 323);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "リリ", "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 2, 4, 0, 1, 40011, 125801, 324);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "クリア", "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 2, 5, 0, 1, 40011, 126001, 325);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (24001, 2, "プレシア", "お兄。\nきてくれて、うれしい", 2, 6, 0, 1, 40011, 126101, 326);
INSERT INTO `v1_35fea868b381ff3e92e98dedfbe0aef2543d365fb8abc57ac66b0a5d7f0afc2d` VALUES (91002, 8, "", "", 0, 1, 532001, 100, 80009, 0, 327);
